static void RemoveICCProfileFromResourceBlock(StringInfo *profile)
{
  size_t length = GetStringInfoLength(profile);
  unsigned char *data = GetStringInfoDatum(profile);
  size_t offset = 0;

  while (offset < length)
  {
    if (length - offset < 14)
      break;

    unsigned int type = PushLongPixel(MSBEndian, (const unsigned char *) data + offset, 0);
    unsigned int size = PushLongPixel(MSBEndian, (const unsigned char *) data + offset + 8, 0);

    if (type == 0x0000040f)
    {
      if (offset + size > length)
        break;

      memmove(data + offset, data + offset + size, length - (offset + size));
      length -= size;
      SetStringInfoLength(profile, length);
      break;
    }

    offset += 14 + size;
  }
}

