static void RemoveICCProfileFromResourceBlock(StringInfo *profile) {
  size_t length = GetStringInfoLength(profile);
  unsigned char *data = GetStringInfoDatum(profile);
  size_t offset = 0;

  while (offset < length - 3) {
    unsigned int signature = 0;
    unsigned short version = 0;

    signature = PushLongPixel(MSBEndian, signature, data + offset);
    if (signature == 0x0000040f) {
      version = PushShortPixel(MSBEndian, version, data + offset + 4);
      if (version == 0x0000) {
        size_t profile_length = PushLongPixel(MSBEndian, 0, data + offset + 8);
        if (offset + profile_length <= length) {
          size_t remaining = length - (offset + profile_length);
          if (remaining > 0) {
            memmove(data + offset, data + offset + profile_length, remaining);
            SetStringInfoLength(profile, length - profile_length);
            length -= profile_length;
          } else {
            SetStringInfoLength(profile, offset);
          }
        }
      }
    }
    offset += 4;
  }
}

static void RemoveICCProfileFromResourceBlock(StringInfo *icc_profile) {
    size_t length = GetStringInfoLength(icc_profile);
    unsigned char *data = GetStringInfoDatum(icc_profile);
    size_t i = 0;

    while (i + 12 <= length) {
        size_t offset = i + 4;
        unsigned int signature = 0;
        signature = (data[offset] << 24) | (data[offset + 1] << 16) |
                    (data[offset + 2] << 8) | data[offset + 3];

        if (signature == 0x0000040f) {
            size_t profile_size = (data[i] << 24) | (data[i + 1] << 16) |
                                  (data[i + 2] << 8) | data[i + 3];
            if (i + profile_size > length)
                return;

            memmove(data + i, data + i + profile_size, length - i - profile_size);
            length -= profile_size;
            SetStringInfoLength(icc_profile, length);
            break;
        }

        i += 12;
    }
}

