static void RemoveICCProfileFromResourceBlock(StringInfo *icc_profile) {
    size_t length;
    unsigned int *p;
    unsigned int signature;
    unsigned int start;
    size::type profile_length;

    if (icc_profile == NULL)
        return;

    length = GetStringInfoLength(icc_profile);
    p = (unsigned int *) GetStringInfoDatum(icc_profile);

    for (start = 0; start < (length - 3);) {
        signature = PushLongPixel(MSBEndian, p);
        if (signature != 0x0000040f)
            p++;
        else {
            size_t remaining;
            unsigned char *q;

            remaining = length - (start * sizeof(*p));
            q = (unsigned char *) p + 4;
            memmove(q - 4, q, remaining);
            length -= 4;
            SetStringInfoLength(icc_profile, length);
            p = (unsigned int *) GetStringInfoDatum(icc_profile);
            length = GetStringInfoLength(icc_profile);
        }
        start++;
    }
}

