static void RemoveICCProfileFromResourceBlock(StringInfo *icc_profile) {
  if (icc_profile == NULL)
    return;

  size_t length = GetStringInfoLength(icc_profile);
  unsigned char *data = GetStringInfoDatum(icc_profile);
  size_t offset = 0;

  while (offset < length - 3) {
    unsigned int tag = (data[offset] << 24) | (data[offset + 1] << 16) |
                      (data[offset + 2] << 8) | data[offset + 3];

    if (tag == 0x0000040f) {
      size_t new_length = length - 4;
      memmove(&data[offset], &data[offset + 4], new_length - offset);
      SetStringInfoLength(icc_profile, new_length);
      return;
    }
    offset += 4;
  }
}

